const state = {page:'company',permission:'manage',saveResult:'success',customer:'lin',tab:'profile',kind:'services',member:0,query:'',type:'全部',owner:'全部',pending:false,listPage:0,businessPage:0,serviceStatus:'待完成',access:'full',feedback:'normal',record:null,scroll:{},font:1};
let sheetTrigger = null;
const customer = () => customers.find(c => c.id === state.customer);
const key = () => state.page === 'directory' ? `directory:${state.query}:${state.type}:${state.owner}:${state.pending}:${state.listPage}` : `${state.page}:${state.customer}:${state.tab}:${state.kind}:${state.businessPage}`;
function saveScroll(){state.scroll[key()] = $('#content').scrollTop;}
function badge(text){const tone = /已完成|有效/.test(text)?'green':/到期|取消|退款/.test(text)?'red':/结束|配送/.test(text)?'blue':'';return `<span class="badge ${tone}">${esc(text)}</span>`;}
function field(label,value){return `<div class="field"><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;}
function fields(items){return `<div class="paper"><dl>${items.map(i=>field(...i)).join('')}</dl></div>`;}
function sections(items,active,action){return `<div class="chips">${items.map(([value,label])=>`<button type="button" data-action="${action}" data-value="${value}" aria-pressed="${active===value}">${label}</button>`).join('')}</div>`;}
function identity(){const c=customer();return `<div class="identity"><div class="avatar" aria-hidden="true">${esc(c.initial)}</div><div class="grow"><h3>${esc(c.name)}</h3><p>${c.type}客户 · 负责人 ${esc(c.owner)}</p></div></div>`;}
function list(){return customers.filter(c=>(state.type==='全部'||c.type===state.type)&&(state.owner==='全部'||c.owner===state.owner)&&(!state.pending||c.pending>0)&&(!state.query||[c.name,c.subtitle,c.owner].some(v=>v.includes(state.query.trim()))));}
function business(){return records.filter(r=>r.customer===state.customer&&r.kind===state.kind&&(state.kind!=='services'||state.serviceStatus==='全部'||r.status==='待完成')).sort((a,b)=>b.date.localeCompare(a.date));}
function pager(page,total,action){const count=Math.max(1,Math.ceil(total/(action==='list-page'?4:3)));return `<div class="pager"><button data-action="${action}" data-value="-1" ${page===0?'disabled':''}>‹ 上一页</button><span>${page+1} / ${count}</span><button data-action="${action}" data-value="1" ${page>=count-1?'disabled':''}>下一页 ›</button></div>`;}
function navigation(){const labels=['首页','公司','日志','AI 地图','我的'],icons=['home','organization','log','ai','person'];return `<nav class="bottom-nav" aria-label="主导航">${labels.map((label,i)=>`<button data-action="main-nav" data-value="${i}" class="${i===1?'active':''}" ${i===1?'aria-current="page"':''}><span><img src="${asset(icons[i])}" alt=""></span>${label}</button>`).join('')}</nav>`;}
function renderHeader(){if(state.page==='editor'){renderEditorHeader();return;}if(['forbidden','expired'].includes(state.feedback)){$('#app-header').innerHTML='<div class="grow"><h2>客户手帐</h2><p>账号访问状态</p></div>';return;}const titles={directory:['客户手帐','每一次来往，都有迹可循'],company:['公司','把工作和客户，放在心上'],customer:['客户详情',customer().type+'客户'],record:['业务记录',customer().name]};const t=titles[state.page];$('#app-header').innerHTML=`${state.page==='directory'?`<button class="icon-button" data-action="company-back" aria-label="返回公司">‹</button>`:state.page==='company'?`<img class="mark" src="${asset('members')}" alt="">`:`<button class="icon-button" data-action="back" aria-label="返回上一层">‹</button>`}<div class="grow"><h2>${t[0]}</h2><p>${esc(t[1])}</p></div>${state.page==='directory'?'<button class="icon-button" data-action="help" aria-label="查看客户手帐说明">?</button>':''}`;}
function renderDirectory(){const rows=list();state.listPage=Math.min(state.listPage,Math.max(0,Math.ceil(rows.length/4)-1));return `<form class="search-form" id="search-form"><input id="search" aria-label="搜索客户" placeholder="搜索客户、企业或负责人" value="${esc(state.query)}" maxlength="60"><button type="submit">搜索</button></form><div class="filter-row">${sections(['全部','个人','企业'].map(x=>[x,x]),state.type,'type')}<button class="icon-button" data-action="filters" aria-label="筛选负责人和待完成服务">筛选${state.owner!=='全部'||state.pending?' •':''}</button></div><div class="list-note"><span>${rows.length} 位客户${state.pending?' · 有待完成服务':''}</span><span>仅显示获准范围</span></div>${rows.length?rows.slice(state.listPage*4,state.listPage*4+4).map(c=>`<button class="customer ${c.type==='企业'?'company':''}" data-action="customer" data-value="${c.id}"><span class="avatar" aria-hidden="true">${esc(c.initial)}</span><span class="grow"><strong>${esc(c.name)}</strong><p>${c.subtitle}</p><p>${c.pending?`待完成服务 ${c.pending} 项`:'暂无待完成服务'} · ${esc(c.owner)}</p></span><span class="chevron" aria-hidden="true">›</span></button>`).join(''):emptyPanel('没有找到匹配客户','试试其他名称，或清空筛选条件。','清空筛选','clear')}<p class="small">个人与企业使用同一份客户目录。</p>`;}
function renderProfile(){return renderEditableProfile();}
function renderMember(){const c=customer();if(!c.members.length)return emptyPanel('暂无会员资格','该客户仍可正常参加活动与接受服务。相关记录在“业务”中查看。','查看业务','go-business');const q=qualifications[c.members[state.member]||c.members[0]];return `${sections(c.members.map((id,i)=>[String(i),id==='club'?'商城会员':'演出年卡']),String(state.member),'member')}<section class="membership"><div class="row"><span class="eyebrow">${q.source}</span>${badge(q.status)}</div><h3>${q.name}</h3><p>有效期 ${q.from} — ${q.until}</p></section>${q.status==='已到期'?'<div class="hint">该资格已到期，权益不可继续使用；历史记录保留。</div>':''}<div class="section-title"><h3>可享权益</h3><span class="small">按当前资格展示</span></div><div class="paper">${q.benefits.map(b=>`<div class="benefit"><div class="grow"><strong>${b[0]}</strong><p class="small">${b[1]}</p></div><span class="balance">${b[2]}</span></div>`).join('')}</div><details><summary>权益使用记录 · ${q.history.length} 条</summary><div class="details-body timeline">${q.history.map(([date,title])=>`<div><b>${title}</b><span>${date}</span></div>`).join('')}</div></details><p class="small">参与活动与使用权益分别记录。</p>`;}
function renderBusiness(){const rows=business();state.businessPage=Math.min(state.businessPage,Math.max(0,Math.ceil(rows.length/3)-1));return `${sections([['services','服务'],['activities','活动'],['orders','订单']],state.kind,'kind')}<div class="list-note"><span>${state.kind==='services'?`${state.serviceStatus}服务`:state.kind==='activities'?'活动参与记录':'商城订单'} · ${rows.length} 条</span>${state.kind==='services'?`<button class="link-button" data-action="service-status">${state.serviceStatus==='待完成'?'查看全部':'只看待完成'}</button>`:'<span>按发生时间排列</span>'}</div>${rows.length?rows.slice(state.businessPage*3,state.businessPage*3+3).map(r=>`<button class="record" data-action="record" data-value="${r.id}"><span class="row"><span class="kind">${r.type}</span>${badge(r.status)}</span><strong>${r.name}</strong><p>${r.date} · ${r.kind==='orders'?(state.access==='limited'?'金额未授权':r.amount):'负责人 '+r.owner}</p></button>`).join(''):emptyPanel('暂无'+({services:'服务',activities:'活动',orders:'订单'}[state.kind])+'记录',state.kind==='services'&&state.serviceStatus==='待完成'?'当前没有待完成服务，可切换查看全部历史。':'此分类目前没有关联记录。')}<p class="small">${state.kind==='orders'?'来源：商城订单记录 · 金额不等同于营收':state.kind==='activities'?'活动状态与服务完成情况分别记录。':'服务完成情况以实际交付记录为准。'}</p>`;}
function renderRecord(){const r=records.find(r=>r.id===state.record);if(!r||r.customer!==state.customer)return emptyPanel('无法访问此记录','请返回客户详情重新选择。','返回客户','back');let data=[['关联客户',customer().name],['业务类型',r.type],['业务日期',r.date]];if(r.kind==='orders'){data.push(['订单来源',r.source],['原实付金额',state.access==='limited'?'未授权':r.amount],['已退款金额',state.access==='limited'?'未授权':r.refund]);}else{data.push(['主要负责人',r.owner],['参与员工',r.staff]);if(r.kind==='services')data.push(['服务依据',r.source]);}return `<div class="list-note"><span>${r.type}</span>${badge(r.status)}</div><h3 class="record-title">${r.name}</h3>${fields(data)}${r.kind==='orders'?`<details><summary>订单编号与来源说明</summary><p>${r.number}<br>${r.description}</p></details>`:`<details><summary>业务说明</summary><p>${r.description}</p></details>`}<details open><summary>${r.kind==='services'?'服务进度':'发生记录'}</summary><div class="details-body timeline">${r.events.map(([date,title])=>`<div><b>${title}</b><span>${date}</span></div>`).join('')}</div></details>${r.kind==='activities'?'<button class="secondary wide" data-action="related-services">查看该客户的服务记录</button>':''}`;}
function emptyPanel(title,message,label,action){return `<div class="state-panel"><img src="../assets/generated_ui/sunshine/mascots/empty.png" alt=""><h3>${title}</h3><p>${message}</p>${label?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;}
function feedback(){const v=state.feedback;if(v==='normal')return '';if(v==='loading')return '<div class="state-panel" role="status"><div class="spinner"></div><h3>正在读取记录</h3><p>请稍候，资料加载后会显示在这里。</p><button class="secondary" data-action="recover">结束加载演示</button></div>';const states={empty:['这里还没有记录','当前范围没有可展示的记录。你可以返回调整筛选。','返回正常示例'],error:['记录暂时没有加载出来','请检查网络后重试，当前筛选会保留。','重新加载'],unavailable:['数据来源暂不可用','这部分资料暂时无法读取，请稍后重试。','重试'],forbidden:['暂时无法访问','当前账号没有此范围的访问权限，请联系管理员。','返回客户目录'],expired:['登录已失效','请重新登录后继续查看客户资料。','重新登录（演示）']};const t=states[v];return `<div class="state-panel" ${v==='error'?'role="alert"':''}><img src="${asset(v==='empty'?'empty':v==='forbidden'?'identity':v==='expired'?'person':'error')}" alt=""><h3>${t[0]}</h3><p>${esc(t[1])}</p><button class="primary" data-action="recover">${t[2]}</button></div>`;}
function renderCompany(){return renderCompanyEntry();}
function renderDock(){if(state.page==='editor'){renderEditorDock();return;}let body='';const blocked=['forbidden','expired'].includes(state.feedback);if(blocked){body='<button class="secondary wide" data-action="exit-state">返回公司</button>';}else if(state.page==='directory'){body=pager(state.listPage,list().length,'list-page')+(canManage()?'<button class="primary wide add-customer" data-action="new-customer">＋ 新增客户</button>':'<p class="readonly-note">当前仅可查看客户资料</p>');}else if(state.page==='company'){body=navigation();}else if(state.page==='customer'){body=(state.tab==='business'&&state.feedback==='normal'?pager(state.businessPage,business().length,'business-page'):'')+`<nav class="dock-tabs" aria-label="客户详情分区" role="tablist">${[['profile','档案'],['member','会员'],['business','业务']].map(([id,label])=>`<button role="tab" aria-selected="${state.tab===id}" aria-controls="detail-panel" id="tab-${id}" data-action="tab" data-value="${id}">${label}</button>`).join('')}</nav><button class="dock-back" data-action="directory">‹ 返回客户目录</button>`;}else{body='<button class="primary wide" data-action="back">‹ 返回客户详情</button>';}$('#dock').innerHTML=body;}
function render({restore=false,focus=false}={}){renderHeader();const blocked=['forbidden','expired'].includes(state.feedback);let html=feedback();if(!html){html=state.page==='editor'?renderEditor():state.page==='directory'?renderDirectory():state.page==='company'?renderCompany():state.page==='record'?renderRecord():`<div id="detail-panel" role="tabpanel" aria-labelledby="tab-${state.tab}">${identity()}${state.tab==='profile'?renderProfile():state.tab==='member'?renderMember():renderBusiness()}</div>`;}else if(state.page==='customer'&&!blocked){html=identity()+html;}$('#content').innerHTML=html;renderDock();$('#content').scrollTop=restore?(state.scroll[key()]||0):0;if(focus)$('#content').focus({preventScroll:true});$('#live').textContent=state.page==='customer'?`${customer().name}，${{profile:'档案',member:'会员权益',business:'业务记录'}[state.tab]}`:({directory:'客户目录',company:'公司',record:'业务记录详情',editor:'客户资料编辑'}[state.page]);syncTools();afterMaintenanceRender();}
function syncTools(){for(const [id,value] of [['preview-font',state.font],['preview-access',state.access],['preview-state',state.feedback],['preview-permission',state.permission],['preview-save',state.saveResult]])$(('#'+id)).value=String(value);}
function transition(fn,restore=false){saveScroll();fn();render({restore,focus:true});}
function openSheet(title,html){if(!$('#sheet').open)sheetTrigger=document.activeElement;$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;$('#sheet').showModal();$('#sheet-close').focus();}
function closeSheet(force=false){if(!force&&guardContactClose())return; $('#sheet').close();if(sheetTrigger?.isConnected)sheetTrigger.focus({preventScroll:true});}
function toolsSheet(){captureEditor();openSheet('原型演示设置',`<p class="small">仅用于评审，全部为合成数据。</p><label>文字大小<select id="sheet-font"><option value="1">标准</option><option value="1.5">放大 1.5 倍</option></select></label><label>返回字段<select id="sheet-access"><option value="full">字段完整</option><option value="limited">联系信息 / 金额受限</option></select></label><label>维护能力<select id="sheet-permission"><option value="manage">可新增与编辑</option><option value="readonly">仅可查看</option></select></label><label>下一次保存<select id="sheet-save"><option value="success">模拟成功</option><option value="error">模拟网络失败</option><option value="conflict">模拟版本冲突</option></select></label><label>页面反馈<select id="sheet-state">${[...$('#preview-state').options].map(o=>`<option value="${o.value}">${o.text}</option>`).join('')}</select></label><button class="primary wide" data-action="apply-tools">应用预览</button>`);$('#sheet-font').value=state.font;$('#sheet-access').value=state.access;$('#sheet-state').value=state.feedback;$('#sheet-permission').value=state.permission;$('#sheet-save').value=state.saveResult;}
function act(action,value){if(maintenanceAction(action,value))return;switch(action){
 case 'customer':transition(()=>{state.customer=value;state.page='customer';state.tab='profile';state.member=0;state.kind='services';state.businessPage=0;state.serviceStatus='待完成';});break;
 case 'directory':transition(()=>{state.page='directory';state.feedback='normal';},true);break;
 case 'back':transition(()=>{state.page=state.page==='record'?'customer':'directory';},true);break;
 case 'type':transition(()=>{state.type=value;state.listPage=0;});break;
 case 'list-page':transition(()=>{state.listPage+=Number(value);});break;
 case 'business-page':transition(()=>{state.businessPage+=Number(value);});break;
 case 'tab':transition(()=>{state.tab=value;if(!['forbidden','expired'].includes(state.feedback))state.feedback='normal';},true);break;
 case 'member':transition(()=>{state.member=Number(value);});break;
 case 'kind':transition(()=>{state.kind=value;state.businessPage=0;});break;
 case 'service-status':transition(()=>{state.serviceStatus=state.serviceStatus==='全部'?'待完成':'全部';state.businessPage=0;});break;
 case 'record':transition(()=>{state.record=value;state.page='record';});break;
 case 'go-business':transition(()=>{state.tab='business';});break;
 case 'related-services':transition(()=>{state.page='customer';state.tab='business';state.kind='services';state.businessPage=0;});break;
 case 'clear':transition(()=>{state.query='';state.type='全部';state.owner='全部';state.pending=false;state.listPage=0;});break;
 case 'recover':transition(()=>{if(state.feedback==='forbidden'||state.feedback==='expired')state.page='directory';state.feedback='normal';});break;
 case 'exit-state':transition(()=>{state.page='company';state.feedback='normal';});break;
 case 'main-nav':if(value==='1'){transition(()=>{state.page='company';state.feedback='normal';});}else{openSheet('既有页面',`<p class="small">${['首页','','日志','AI 地图','我的'][value]}沿用当前 App。本原型聚焦公司里的客户查询体验。</p><button class="primary wide" data-action="close">继续查看客户原型</button>`);}break;
 case 'help':openSheet('一本手帐，三类信息','<div class="paper"><div class="contact"><strong>档案</strong><p class="small">客户身份、联系人与负责人。</p></div><div class="contact"><strong>会员</strong><p class="small">会员资格、年卡、有效期和权益使用。</p></div><div class="contact"><strong>业务</strong><p class="small">服务、活动与订单，点开查看独立记录。</p></div></div>');break;
 case 'filters':openSheet('筛选客户',`<label>业务负责人<select id="filter-owner"><option>全部</option><option>陈晨</option><option>许禾</option></select></label><label class="choice"><input id="filter-pending" type="checkbox" ${state.pending?'checked':''}>只看有待完成服务的客户</label><div class="actions"><button class="secondary" data-action="reset-filters">重置</button><button class="primary" data-action="apply-filters">查看客户</button></div>`);$('#filter-owner').value=state.owner;break;
 case 'reset-filters':$('#filter-owner').value='全部';$('#filter-pending').checked=false;break;
 case 'apply-filters':state.owner=$('#filter-owner').value;state.pending=$('#filter-pending').checked;state.listPage=0;closeSheet();render({focus:true});break;
 case 'apply-tools':state.permission=$('#sheet-permission').value;state.saveResult=$('#sheet-save').value;state.font=Number($('#sheet-font').value);state.access=$('#sheet-access').value;state.feedback=$('#sheet-state').value;$('#device').style.setProperty('--scale',state.font);closeSheet();render({focus:true});break;
 case 'close':closeSheet();break;
}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action)act(b.dataset.action,b.dataset.value);if(b.dataset.scene){if(guardSceneChange(b.dataset.scene))return;transition(()=>{state.feedback='normal';state.page=b.dataset.scene==='entry'?'company':b.dataset.scene==='directory'?'directory':'customer';state.customer=b.dataset.scene==='company'?'heyu':'lin';state.tab=b.dataset.scene==='person'?'member':'business';state.kind='activities';state.member=0;state.businessPage=0;});}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['profile','member','business'],i=tabs.indexOf(state.tab),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;act('tab',tabs[next]);$('#tab-'+tabs[next]).focus({preventScroll:true});}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=$('#search').value.trim();state.listPage=0;render({focus:true});}});
$('#sheet-close').onclick=()=>closeSheet();$('#tools-open').onclick=toolsSheet;
$('#sheet').addEventListener('cancel',e=>{e.preventDefault();closeSheet();});
$('#sheet').addEventListener('click',e=>{const r=$('#sheet').getBoundingClientRect();if(e.target===$('#sheet')&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeSheet();});
$('#preview-width').onchange=e=>{$('#device').style.width=e.target.value+'px';};
$('#preview-font').onchange=e=>{state.font=Number(e.target.value);$('#device').style.setProperty('--scale',state.font);};
$('#preview-access').onchange=e=>{captureEditor();state.access=e.target.value;render();};
$('#preview-state').onchange=e=>{captureEditor();state.feedback=e.target.value;render();};
